<template><view class="panel submission"><view class="row between"><view class="row"><text class="badge">{{ kindLabel[record.kind] }}{{ record.payload.recipeId ? ' · 修改' : '' }}</text><text class="record-title">{{ record.payload.name || record.payload.title || '意见反馈' }}</text></view><text class="badge" :class="record.status">{{ statusLabel[record.status] }}</text></view><view class="muted meta">#{{ record.id }} · {{ record.author.nickname }} · {{ date(record.createdAt) }}</view><template v-if="record.kind === 'recipe'"><view class="record-text">店铺：{{ record.payload.restaurantName }}</view><view class="record-text">{{ record.payload.description }}</view><view v-if="record.payload.servingNote" class="muted">分量：{{ record.payload.servingNote }}</view><view class="recipe-items"><view v-for="it in record.payload.items" :key="it.condimentId">{{ it.condimentName }} · {{ levels[it.amountLevel] }}<text v-if="it.amountNote">（{{ it.amountNote }}）</text></view></view><view class="photo-grid"><image v-for="img in record.payload.images" :key="img.id" class="photo" mode="aspectFill" :src="mediaUrl(img.url)" @click="preview(img.url)" /></view></template><template v-else-if="record.kind === 'restaurant'"><view class="record-text">{{ record.payload.category }} · {{ record.payload.note || '无补充说明' }}</view></template><view v-else class="record-text">{{ record.payload.content }}</view><view v-if="record.reviewNote" class="review-note">审核意见：{{ record.reviewNote }}</view><view v-if="record.reviewedAt" class="muted meta">{{ record.reviewer }} · {{ date(record.reviewedAt) }}</view><button v-if="record.publishedId" class="ghost published-link" @click="published">查看已发布内容 ↗</button><slot /></view></template>
<script setup>
import { kindLabel, statusLabel, mediaUrl } from '../api/community.js'
const props = defineProps({ record: { type: Object, required: true } })
const levels = ['不放', '一点点', '少量', '适量', '偏多', '多放']
const date = value => value ? new Date(value).toLocaleString('zh-CN') : ''
function published() { uni.navigateTo({ url: `/pages/${props.record.kind === 'restaurant' ? 'restaurant' : 'recipe'}/detail?id=${props.record.publishedId}` }) }
function preview(url) { uni.previewImage({ current: mediaUrl(url), urls: props.record.payload.images.map(i => mediaUrl(i.url)) }) }
</script>
<style scoped>.record-title { font-size: 17px; font-weight: 600; }.meta { font-size: 12px; margin: 12px 0; }.record-text { margin: 12px 0; font-size: 15px; white-space: pre-wrap; overflow-wrap: anywhere; }.recipe-items { padding: 15px 18px; margin: 15px 0; background: #f8f5ef; border-radius: 10px; font-size: 14px; line-height: 2; }.review-note { background: #fff1e7; color: #9f5c39; padding: 13px; border-radius: 8px; margin: 14px 0; font-size: 14px; white-space: pre-wrap; }.published-link { margin-top: 16px; }</style>
